#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int maxn = 505;
int n, m, mod;
inline int add(int x, int y) {
    int sum = x + y;
    return sum >= mod ? sum - mod : sum;
}
inline int multiply(int x, int y) { return (ll) x * y % mod; }
int C[maxn][maxn];
int f[maxn], g[maxn];
int F[maxn][maxn], G[maxn][maxn];

int main() {
    scanf("%d%d%d", &n, &m, &mod);
    for (int i = 0; i <= n; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = add(C[i - 1][j - 1], C[i - 1][j]);
        }
    }
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            int temp1 = multiply(multiply(f[j - 1], f[i - j]), multiply(i + 1, C[i - 1][j - 1]));
            f[i] = add(f[i], temp1);
            int temp2 = multiply(multiply(f[j - 1], g[i - j]), multiply(i + 1, C[i - 1][j - 1]));
            g[i] = add(g[i], temp2);
            int temp3 = multiply(multiply(g[j - 1], f[i - j]), multiply(i + 1, C[i - 1][j - 1]));
            g[i] = add(g[i], temp3);
            int temp4 = multiply(multiply(f[j - 1], f[i - j]), multiply(add(C[j][2], C[i - j + 1][2]), C[i - 1][j - 1]));
            g[i] = add(g[i], temp4);
        }
    }
    F[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        F[i][i] = f[i];
        G[i][i] = g[i];
        for (int j = 0; j <= min(i - 1, m); j++) {
            for (int l = 0; l <= j; l++) {
                G[i][j] = add(G[i][j], multiply(multiply(g[l], F[i - l - 1][j - l]), C[j][l]));
                F[i][j] = add(F[i][j], multiply(multiply(f[l], F[i - l - 1][j - l]), C[j][l]));
                G[i][j] = add(G[i][j], multiply(multiply(f[l], G[i - l - 1][j - l]), C[j][l]));
            }
        }
    }
    cout << G[n][m] << endl;
    return 0;
}
